import{_ as a,H as e,f as n,i as p}from"./chunks/framework.BH2BK_3i.js";const u=JSON.parse('{"title":"13-材料整理：从混乱到秩序，以说代做","description":"","frontmatter":{},"headers":[{"level":2,"title":"梳理框架：更多思考，更少执行","slug":"梳理框架-更多思考-更少执行","link":"#梳理框架-更多思考-更少执行","children":[]},{"level":2,"title":"切入：捋需求，抓重点","slug":"切入-捋需求-抓重点","link":"#切入-捋需求-抓重点","children":[]},{"level":2,"title":"秘诀：兼收并蓄","slug":"秘诀-兼收并蓄","link":"#秘诀-兼收并蓄","children":[{"level":3,"title":"✦ 特殊任务：空手套白狼","slug":"✦-特殊任务-空手套白狼","link":"#✦-特殊任务-空手套白狼","children":[]},{"level":3,"title":"✦ 主线任务 1：单次整理","slug":"✦-主线任务-1-单次整理","link":"#✦-主线任务-1-单次整理","children":[]},{"level":3,"title":"✦ 主线任务 2：智能填充","slug":"✦-主线任务-2-智能填充","link":"#✦-主线任务-2-智能填充","children":[]},{"level":3,"title":"✦ 主线任务 3：拆分整理","slug":"✦-主线任务-3-拆分整理","link":"#✦-主线任务-3-拆分整理","children":[]}]},{"level":2,"title":"边整理边用","slug":"边整理边用","link":"#边整理边用","children":[]},{"level":2,"title":"小黑板","slug":"小黑板","link":"#小黑板","children":[]},{"level":2,"title":"踏浪扬帆","slug":"踏浪扬帆","link":"#踏浪扬帆","children":[]},{"level":2,"title":"附：整理 prompt","slug":"附-整理-prompt","link":"#附-整理-prompt","children":[]}],"relativePath":"零基础GPT应用入门课/13-材料整理：从混乱到秩序，以说代做.md","filePath":"零基础GPT应用入门课/13-材料整理：从混乱到秩序，以说代做.md","lastUpdated":1795561467000}'),t={name:"零基础GPT应用入门课/13-材料整理：从混乱到秩序，以说代做.md"};function i(l,s,o,E,c,h){return e(),n("div",null,[...s[0]||(s[0]=[p(`<h1 id="_13-材料整理-从混乱到秩序-以说代做" tabindex="-1">13-材料整理：从混乱到秩序，以说代做 <a class="header-anchor" href="#_13-材料整理-从混乱到秩序-以说代做" aria-label="Permalink to &quot;13-材料整理：从混乱到秩序，以说代做&quot;">​</a></h1><p>你好，我是键盘，我们继续驯服 GPT。</p><p>想要使用 GPT 来提效，除了基础的翻译和行动指引，离我们最近的其实还是材料整理。这个课题会有点大，毕竟文字材料以外也还有图、文、音等多模态数据。所以我们从中抽取一个“文件整理”，解决它，之后再延伸应用也就轻而易举了。</p><p>整理什么文件呢？为了不让你错过绘图 AI，接下来我们就整理一套 AI 绘图概念词典，让你想要的时候随手就有一份参考。这份参考适用于 Midjourney、Stable Diffusion 等等文生图模型。</p><p>我们梳理一下材料整理的准备工作和效果预期。</p><ul><li><p>情况一：你已经在文本工具中储备了少量零散概念，属于整理你已有的东西，效果最佳。</p></li><li><p>情况二：你有一份网上捞过来的参考词典，可行。唯一的问题是，这是别人整理的，没有投入你个人知识的涟漪，不好用。</p></li><li><p>情况三：整理几乎不了解的材料，还是能实现。我们先给 GPT 投一个小石头，激起第一道涟漪，空手套白狼。</p></li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>……我是新手，针对&quot;色彩&quot;，请按&lt;单词+描述&gt;，填充 30 组整理好的数据表格。</span></span></code></pre></div><p>我会重点分享第一种情况，同时提供第三种情况兼容新手的方案。通过案例的实践，你将掌握4 个可复用的技巧。</p><ol><li><p>在 GPT 对话框中对数据进行聚类、排序。</p></li><li><p>一行指令对长输入 / 输出进行拆分。</p></li><li><p>智能的数据校对，防止错漏和重复。</p></li><li><p>智能填充和扩展。</p></li></ol><p>这节课的实操首选稳定的 GPT-4 模型，因为 ChatGPT 稳定性较差，校对环节会比较影响效率。</p><h2 id="梳理框架-更多思考-更少执行" tabindex="-1">梳理框架：更多思考，更少执行 <a class="header-anchor" href="#梳理框架-更多思考-更少执行" aria-label="Permalink to &quot;梳理框架：更多思考，更少执行&quot;">​</a></h2><p>我们要明确的是，这个整理不是要强行以 AI 的方式来执行，为了用而用，而是通过思考日常整理材料的难点，想一想怎么样整理才会更方便，理清整理材料和使用 GPT 在实际工作中的结合点。</p><p>为了让后续挑战更加轻松，我们先来做好前置准备。</p><p>✦ 规避无意识的概念盲区</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>设计 prompt 最怕一上来就写 整理一份Midjourney的prompt词典 这类主题。即使你使用的</span></span></code></pre></div><p>是更高级的 GPT-4，它们 2011 年的出生点就意味着一些概念是不存在的，比如这里的Midjourney。</p><p>那怎么有意识地兼容孤岛模型和联网插件呢？答案是加上明确的、附带目的的描述“什么样的Midjourney”。</p><ul><li>prompt 实例</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>整理一份AI绘图工具Midjourney的prompt词典…… #其他细节</span></span></code></pre></div><p>也就是将盲区词汇“Midjourey”作为明确目的，“AI 绘图”作为附加词，这样向上兼容联网模型的时候，GPT 就会知道这是一个 AI 绘图工具 Midjourney，不是路人甲、乙、丙 Midjourey。</p><p>✦ 应对局限：分类输入 / 输出</p><p>比起用 Python 来写一个自动化处理方案，打开 ChatGPT 就能分类整理的方式更适合小白。但因为字数限制，可以预见的结果就是频繁中断、大量错漏，或者干脆不支持超过 1000 字的材料。不用怕，用讲过的分段策略来解决就好。</p><p>✦ 提取要素：明确整理的维度细节</p><p>假如你要整理的材料来自完全不了解的新领域，又该怎么下手？没关系，先来建立知识的联结。比如 AI 绘图领域，本质上就是用语言描述出一个画面，你可以理解为“讲故事”。那么 AI绘图领域的 5 要素，就可以投射到我们讲过的“提问 5 要素”中去理解。它的 5 要素就可以是：</p><ul><li>谁（和谁）+ 在哪里 + 做什么 + 什么时间 + 怎么做</li></ul><p>不过，现在的绘图 5 要素还不足以形成清晰、明确的描述。比如说“一只狗”，一只什么样的狗？“什么样”这个概念才是让画面变具体的关键。好，继续往下拆解。一个具体的画面可以用不同的属性来描述，比如画面“蜿蜒的小河边，在大树上有一个木头树屋，斑驳的阳光，居中构图，远景，低视角，宁静的手绘”，它可以拆解为 7 个维度：</p><ul><li>色彩 + 光线 + 材质 + 构图 + 景别 + 视角 + 风格</li></ul><p>到这一步，就是专业和非专业户的分水岭了，完全不懂的话，你也可以先让 GPT 给出明确的拆解参考。这些具体的分类清晰之后，就可以设计 prompt 了。</p><h2 id="切入-捋需求-抓重点" tabindex="-1">切入：捋需求，抓重点 <a class="header-anchor" href="#切入-捋需求-抓重点" aria-label="Permalink to &quot;切入：捋需求，抓重点&quot;">​</a></h2><p>任何 prompt 的设计都要根据实际情况来思考，所以我们先从手头已有的待整理数据来分析。</p><p>我从开始用 Midjourney 时记录的碎片信息里面摘出了一段“光线”分类。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>……</span></span>
<span class="line"><span>morning light 晨光</span></span>
<span class="line"><span>dappled sunlight 斑驳的阳光（验证：komorebi 木漏れ日，MJ无法识别，使用 sunlight filteri</span></span>
<span class="line"><span>golden hour 黄金时段（日落前和日出后的一小时，全天最柔和的暖光）</span></span>
<span class="line"><span>twilight 暮色 surrounded in golden twilight 被金色的暮色笼罩</span></span>
<span class="line"><span>……</span></span>
<span class="line"><span>光/方向</span></span>
<span class="line"><span>rembrandt light 伦勃朗式用光</span></span>
<span class="line"><span>top light 顶光</span></span>
<span class="line"><span>……</span></span></code></pre></div><p>这个类目近百行，有些概念包含实践过后打上的评级，有些包含相应的描述，大部分因为我自己了解，就只提供了简单的中、英文名称。假如靠人力去调整位置和细节，至少要费半天的时间，所以提效还得是 AI。</p><p>最基础的整理，一般能够梳理出 7 个常规的需求点。</p><ol><li><p>使用表格来结构化整理：纯文字可用性和可读性都很差，也不方便用于协作。</p></li><li><p>区分不同的输出模版：比如说色彩类目可以单独多加一个色卡，展现概念“本色”。</p></li><li><p>统一整理的维度：通常就是定义用哪些类型的数据列，还有确认某些列的对齐方式。比如数额类数据因为要便于分辨位数，所以右对齐基本就是标配。</p></li><li><p>数据聚类：细分二级分类，相似的就自动归类。</p></li><li><p>按一定的规律排序：保持所谓的秩序，方便关联记忆，毕竟最后这份材料要落到实际应用。</p></li><li><p>按需填充必要的描述：做到心中有概念，而不是光有一个词。</p></li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>整理格式：为了方便阅读，除了专有名词，如 Pixar、C4D ，其他名词统一小写。</span></span></code></pre></div><p>再针对这个场景补充 2 个必要的需求。</p><ol><li>拆分</li></ol><p>个别输入 / 输出会很长，这是一个你可以预判到的、会严重影响效率的地方。那是不是可以设</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>计 datas 和 output  分支指令，按分段输入，按二级分类输出？这样既保障了数据结构，</span></span></code></pre></div><p>又能规避大量的中断。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/13-%25E6%259D%2590%25E6%2596%2599%25E6%2595%25B4%25E7%2590%2586/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/13-%25E6%259D%2590%25E6%2596%2599%25E6%2595%25B4%25E7%2590%2586/1.png" alt=""></a></p><ol start="2"><li>校对</li></ol><p>只要是涉及数据和信息的整理，校对这个环节必不可少。比如说统计财务数据，一条错漏足以作废整份结果。这里我提供 4 个维度，数目统计、智能纠错（含大小写规则）、查漏补缺、自动去重，都可以写在 prompt 里，帮你保障输出质量。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/13-%25E6%259D%2590%25E6%2596%2599%25E6%2595%25B4%25E7%2590%2586/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/13-%25E6%259D%2590%25E6%2596%2599%25E6%2595%25B4%25E7%2590%2586/2.png" alt=""></a></p><h2 id="秘诀-兼收并蓄" tabindex="-1">秘诀：兼收并蓄 <a class="header-anchor" href="#秘诀-兼收并蓄" aria-label="Permalink to &quot;秘诀：兼收并蓄&quot;">​</a></h2><p>针对这种需求点繁多的情况，很可能出现不断地复制模板、改模板的问题。比如整理完色彩又要设计一条专用于整理光线的 prompt，然后还要设计材质、构图、景别等等其他分类。所以，我们使用打包指令集，借助之前提到的“变量”来灵活应变。prompt 稍后再写，这里先提示你 2 个关键方法。</p><p>方法 1，从一个分类开始，覆盖其他需求场景。什么意思呢？刚入门时我采用的是分开设计并处理的方法，7 大类就要设计对应的 7 条 prompt，很麻烦。但是每个需求场景一定会有共性需求，我们来找到它们。</p><p>比如基础的聚类整理和校对、更细致的差异化输出，这种共性需求就可以抽象出来。你还可以</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>利用好 AI 的推理优势，针对已经初步整理的材料设计智能填充模式 /fill ，接着已经整理好</span></span>
<span class="line"><span>的内容继续填充。如果你对整理的领域完全不了解，还可以设计一个新手模式 /oops ，空手</span></span></code></pre></div><p>套白狼，让 GPT 自己生成、自己整理。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#入门时期设计的&quot;构图&quot;整理</span></span></code></pre></div><ul><li>用表格将以下数据按进行归类呈现，使阅读顺序上富有逻辑。要求：</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1、排序依据可以是：近似就近排列</span></span>
<span class="line"><span>2、使用「prompt」、「中文」、「评级」、「备注」4列，「评级」只有和，原数据未标示的留空。原括号内的信</span></span>
<span class="line"><span>3、检查数据条目，核对是否有遗漏，给出答复和数量条目数。</span></span>
<span class="line"><span>4、仅当遗漏的情况补全数据，不需要重复其余表格。</span></span>
<span class="line"><span>---</span></span>
<span class="line"><span>#我的数据</span></span></code></pre></div><ul><li>凌乱的数据</li></ul><p>方法 2，拆或不拆，用一个指令打包。简单来说，整理材料这个场景的特殊点在于我们可能会分多次输入，也可能不会。那这两种情况要分开定义吗？不用。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>对于输入来说，使用 /datas：用户可能会拆分多次输入  就比多写一条 /data：用户输入数</span></span></code></pre></div><p>据，进入整理 的效果要好，因为“可能会拆分”就包括了拆或不拆 2 种情况，没有必要多写一条</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>分支。而对于输出，设定一个暗号 /output  自动触发处理就好，用户侧只需要不断回“1”确</span></span></code></pre></div><p>认，直到全部输出。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#写法1——分开定义，有重合的地方</span></span>
<span class="line"><span>/data：用户输入数据，进入整理</span></span>
<span class="line"><span>/datas：用户拆分多次输入……/用户可能会拆分多次输入……</span></span>
<span class="line"><span>#写法2——有效合并，1个指令覆盖2种情况</span></span>
<span class="line"><span>/datas：用户可能会拆分多次输入……</span></span></code></pre></div><p>有了这两个方法，就可以在 指令 定义里面“转述”需求，快速完成 prompt 设计了。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/13-%25E6%259D%2590%25E6%2596%2599%25E6%2595%25B4%25E7%2590%2586/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/13-%25E6%259D%2590%25E6%2596%2599%25E6%2595%25B4%25E7%2590%2586/3.png" alt=""></a></p><ul><li>初始 prompt</li></ul><p>对于“材料整理”这类要求比较严谨的情况，我们可以让 AI 指出设计存在的不足，主动迭代一次。和之前根据结果来被动迭代不同，你会得到一些意想不到的收获。</p><ul><li>主动让 AI 指导，让逻辑更缜密</li></ul><p>ChatGPT 偶尔会在没有要求的情况下自己说出对任务或步骤的理解。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/13-%25E6%259D%2590%25E6%2596%2599%25E6%2595%25B4%25E7%2590%2586/4.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/13-%25E6%259D%2590%25E6%2596%2599%25E6%2595%25B4%25E7%2590%2586/4.png" alt=""></a></p><ul><li>允许 AI 自发说明步骤</li></ul><p>这种情况，不需要强制要求“不要解释”。从任务结果的角度，它的确是多余的，但从 AI 运作逻辑的角度，明牌的理解远远好过暗箱的结果。</p><h3 id="✦-特殊任务-空手套白狼" tabindex="-1">✦ 特殊任务：空手套白狼 <a class="header-anchor" href="#✦-特殊任务-空手套白狼" aria-label="Permalink to &quot;✦ 特殊任务：空手套白狼&quot;">​</a></h3><p>Prompt 准备好，我们先来跑一个手里没有任何数据的特殊情况。只要单独定义一条兼容新手的指令就能实现。</p><ul><li>prompt</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/oops：用户是新手，他会输入一个分类名，请按&lt;​Phrase+中文+备注&gt;填充 30 组整理好的数据表格。</span></span></code></pre></div><ul><li>🤖️ ChatGPT</li></ul><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/13-%25E6%259D%2590%25E6%2596%2599%25E6%2595%25B4%25E7%2590%2586/5.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/13-%25E6%259D%2590%25E6%2596%2599%25E6%2595%25B4%25E7%2590%2586/5.png" alt=""></a></p><p>这里也提供一种极致压缩的指令方式，功能指令加上数量，能够直接覆盖数量的默认值。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/13-%25E6%259D%2590%25E6%2596%2599%25E6%2595%25B4%25E7%2590%2586/6.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/13-%25E6%259D%2590%25E6%2596%2599%25E6%2595%25B4%25E7%2590%2586/6.png" alt=""></a></p><ul><li>不需要声明变量的方式</li></ul><h3 id="✦-主线任务-1-单次整理" tabindex="-1">✦ 主线任务 1：单次整理 <a class="header-anchor" href="#✦-主线任务-1-单次整理" aria-label="Permalink to &quot;✦ 主线任务 1：单次整理&quot;">​</a></h3><p>无中生有都能解决，其他的就更有信心了。我们回到主线任务整理已有的数据。先采用刚才AI 提出的好建议，让正式 prompt 更简洁好用。（prompt 附录可见）</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/13-%25E6%259D%2590%25E6%2596%2599%25E6%2595%25B4%25E7%2590%2586/7.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/13-%25E6%259D%2590%25E6%2596%2599%25E6%2595%25B4%25E7%2590%2586/7.png" alt=""></a></p><ul><li>整理类 prompt 设计</li></ul><p>先挑一个分类进行整理，这里选择了词条相对少的“色彩”，因此不需要拆分多次输入。我这里</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>的设计是在 /datas 模式下输入一次数据。为了减少会话，你还可以参考下面 prompt 里的 3</span></span>
<span class="line"><span>个减号 --- ，用它隔断数据，再合入暗号“1”，自动触发 /output 模式，由 GPT 输出已经整</span></span></code></pre></div><p>理好的内容。</p><ul><li>prompt</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#数据</span></span>
<span class="line"><span>---</span></span>
<span class="line"><span>1 其他要求补充(如有)</span></span></code></pre></div><p>需要注意的是，GPT-4 对这种合并表达的理解更稳定，但对 ChatGPT 弟弟来说，单独多发一条暗号更稳妥。</p><ul><li>分类整理：色彩</li></ul><p>输出结果中，除了有鸢尾色、丁香色、红宝石色这些狭义上的色彩名称，还有浅色调、柔和、莫兰迪、活力等等色彩感受。这些词混合在一起，二级分类的细节没有体现出来。怎么办呢？你可以单独要求整理一类带色卡的，暗示 GPT 在后续的任务中记住细分类目这件事。</p><h3 id="✦-主线任务-2-智能填充" tabindex="-1">✦ 主线任务 2：智能填充 <a class="header-anchor" href="#✦-主线任务-2-智能填充" aria-label="Permalink to &quot;✦ 主线任务 2：智能填充&quot;">​</a></h3><p>单次整理之后，可能还有继续补充数据的需求，甚至可能你自己都不记得是不是整理过这个类</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>目了。所以针对 /fill 分支，我设计了容错判断，假如某个分类已经有整理好的数据了，那</span></span></code></pre></div><p>就在此基础上沿用规格和格式来填充更多，否则就让用户提供需要整理的数据。</p><p>比如现在“色彩”已经确认满意了，那就可以在效果可预期的情况下填充更多，节省人力。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/13-%25E6%259D%2590%25E6%2596%2599%25E6%2595%25B4%25E7%2590%2586/8.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/13-%25E6%259D%2590%25E6%2596%2599%25E6%2595%25B4%25E7%2590%2586/8.png" alt=""></a></p><ul><li>利用好 AI 的优势，智能填充</li></ul><h3 id="✦-主线任务-3-拆分整理" tabindex="-1">✦ 主线任务 3：拆分整理 <a class="header-anchor" href="#✦-主线任务-3-拆分整理" aria-label="Permalink to &quot;✦ 主线任务 3：拆分整理&quot;">​</a></h3><p>在“光线”类目里，我准备了相对较多的零散词条。这种数据储备在其他分类没问题的前提下解决，效果会更好。</p><p>先来搞定拆分输入。现在 GPT 还没办法直接输入文档，所以我们粘贴数据就好，不用关心格式和词条里各个描述维度的位置。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/13-%25E6%259D%2590%25E6%2596%2599%25E6%2595%25B4%25E7%2590%2586/9.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/13-%25E6%259D%2590%25E6%2596%2599%25E6%2595%25B4%25E7%2590%2586/9.png" alt=""></a></p><ul><li>拆分输入</li></ul><p>用暗号“1”让 AI 知道输入完事了，接着逐块拿到输出。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/13-%25E6%259D%2590%25E6%2596%2599%25E6%2595%25B4%25E7%2590%2586/10.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/13-%25E6%259D%2590%25E6%2596%2599%25E6%2595%25B4%25E7%2590%2586/10.png" alt=""></a></p><ul><li>拆分输出</li></ul><p>这个 Emoji 和二级分类名，除了承担拆分输出的作用，最后我们将数据粘贴到表格文档中的时候，它们还有清晰地划分模块的作用。</p><p>其他比“光线”相对次要的分类，按同样的方式来输入输出即可，也可以参考“色彩”分类，按需定义差异化的输出表格。你想自动配图也可以，基础课程中我也分享过方法。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/13-%25E6%259D%2590%25E6%2596%2599%25E6%2595%25B4%25E7%2590%2586/11.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/13-%25E6%259D%2590%25E6%2596%2599%25E6%2595%25B4%25E7%2590%2586/11.png" alt=""></a></p><ul><li>整理成果展现</li></ul><h2 id="边整理边用" tabindex="-1">边整理边用 <a class="header-anchor" href="#边整理边用" aria-label="Permalink to &quot;边整理边用&quot;">​</a></h2><p>存数据的过程相对枯燥，不过我们不用等材料都整理完了再用来出图，直接来看怎么玩。按惯例还是由首席执行官 ChatGPT 完成初始画面，我给你安排了一段极简提词器，这是用于衍生一切复杂提词器产品的精华。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你是一个专业AI画师，请生成一组清晰、明确的关键词来描述一个具体的主题画面。步骤：</span></span>
<span class="line"><span>1、描述画面细节，重点加粗：</span></span>
<span class="line"><span>- 主题</span></span>
<span class="line"><span>- 色彩,光线,材质,构图,景别,视角</span></span>
<span class="line"><span>- 风格</span></span>
<span class="line"><span>2、用英文提炼为一个prompt，模版：</span></span>
<span class="line"><span>## 🔮 PROMPT</span></span>
<span class="line"><span>*Subject,color，...,style --ar w:h* #w:h：appropriate aspect ratio。</span></span>
<span class="line"><span>---</span></span></code></pre></div><ul><li>主题：枫林日落</li></ul><p>这段 prompt 里，步骤 1 是精华中的精华，主题 + 维度。</p><ul><li>🤖️ ChatGPT</li></ul><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/13-%25E6%259D%2590%25E6%2596%2599%25E6%2595%25B4%25E7%2590%2586/12.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/13-%25E6%259D%2590%25E6%2596%2599%25E6%2595%25B4%25E7%2590%2586/12.png" alt=""></a></p><p>绘图词典已经囊括了色彩、光线、材质、构图、景别、视角等等画面细节，如果你还有精确控制画面的需求，比如说把 GPT 生成的天青色改成雾茫茫，从词典中挑出目标词汇来替换即可。下面是一个调整后的示例。</p><ul><li>🪄 Image Prompt（Midjourney）</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Maple Forest Sunset, cozycore, soft light, progressive composition, romantic atma</span></span></code></pre></div><ul><li>🗣️ 人话</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>枫林日落，舒适内核，软光，渐进式构图，浪漫氛围，编辑精选照片，画幅比例 16:9</span></span></code></pre></div><ul><li><p>🤖️ Midjourney</p></li><li><p>啥也不懂也能画</p></li></ul><h2 id="小黑板" tabindex="-1">小黑板 <a class="header-anchor" href="#小黑板" aria-label="Permalink to &quot;小黑板&quot;">​</a></h2><p>这节课我们使用 ChatGPT 来整理材料。要记得，整理之前，思考先行。</p><p>我们不是为了整理而整理，而是通过这个方式，掌握将 ChatGPT 结合到实际需求场景的思路，把主动的整理和实践中的思考结合起来，再配合整理过程中的“评级”和“备注”，把碎片化知识吃透。</p><p>我分享了 3 种实用的方法，让整理更轻松。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/13-%25E6%259D%2590%25E6%2596%2599%25E6%2595%25B4%25E7%2590%2586/13.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/13-%25E6%259D%2590%25E6%2596%2599%25E6%2595%25B4%25E7%2590%2586/13.png" alt=""></a></p><ul><li>思考先行</li></ul><p>以“AI 绘图词典”为例，我展示了使用 GPT 来整理凌乱的信息碎片的方法。首先从需求侧切入，捋出基础的 7 个整理需求和需要重点关注的拆分和智能校对。可以看到，因为需求繁多，不断改模版的方式就显得很低效，所以我建议设计一个兼收并蓄的 prompt，方便打包解决。设计初始 prompt 之后，我们再学习一种主动迭代的方法，让 AI 指导整理逻辑上存在的不足，让后续的工作更加缜密。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/13-%25E6%259D%2590%25E6%2596%2599%25E6%2595%25B4%25E7%2590%2586/14.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/13-%25E6%259D%2590%25E6%2596%2599%25E6%2595%25B4%25E7%2590%2586/14.png" alt=""></a></p><ul><li>2 个兼容并蓄的方法</li></ul><p>整理的主线是针对手头已有的零碎信息，因为有个人的思考投入，整理成果才能真正变得好用。整理的支线是设计一行兼容小白的指令，实现空手也能套白狼。通过整理实例，希望你能掌握 5 条整理技巧。</p><ol><li><p>允许 AI 自发输出理解，明牌执行。</p></li><li><p>在 GPT 对话框中对数据进行聚类、自动排序。</p></li><li><p>一行指令拆分长输入 / 输出。</p></li><li><p>智能数据校对，防止错漏和重复。</p></li><li><p>用好 AI 的优势，智能填充更多内容。</p></li></ol><p>借由解决“文件整理”这个问题，你还可以展望其他的应用可能性。除了本节的 AI 绘图词典整理，你还可以将这个方法用到文件归档、整理网络收藏夹、笔记、图片和信息等等，或者是针对高品质的交流群，用来总结群聊重点并归类。</p><p>如果需要文件权限和自动化的整理，还可以要求 GPT 输出 Python 解决方案，一般就是利用os 库来读取本地文件，自动操作。本质上它们都是分类并整理，利用强大的 AI 来消灭碎片信息，对于个人的知识体系化形成，还有更大的价值。</p><p>要点：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/13-%25E6%259D%2590%25E6%2596%2599%25E6%2595%25B4%25E7%2590%2586/15.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80GPT%E5%BA%94%E7%94%A8%E5%85%A5%E9%97%A8%E8%AF%BE/images/13-%25E6%259D%2590%25E6%2596%2599%25E6%2595%25B4%25E7%2590%2586/15.png" alt=""></a></p><ul><li>小彩蛋用于整理的 prompt：ChatGPT x Mermaid x fontawesome 图标嵌入</li></ul><h2 id="踏浪扬帆" tabindex="-1">踏浪扬帆 <a class="header-anchor" href="#踏浪扬帆" aria-label="Permalink to &quot;踏浪扬帆&quot;">​</a></h2><p>假如你手上什么都没有，用“空手套白狼”的方式试试能否整成功，然后参考这一节的方法，自选整理目标，尽量将手头的碎片化材料串成体系。</p><p>期待在评论区看到你的思考或感受分享，也欢迎你将这节课分享给感兴趣的朋友们，戳此加入课程交流群，我们下节课再会。</p><h2 id="附-整理-prompt" tabindex="-1">附：整理 prompt <a class="header-anchor" href="#附-整理-prompt" aria-label="Permalink to &quot;附：整理 prompt&quot;">​</a></h2><ul><li><p>适用：ChatGPT。</p></li><li><p>表现更佳：GPT-4。</p></li><li><p>字数：540</p></li><li><p>声明：该 prompt 仅供个人参考学习，未经授权不可商用。</p></li><li><p>你是一位精通智能绘画领域的画师。请根据以下说明，使用表格对用户提供的数据进行整理和校对。</p></li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>初始化模版：{</span></span>
<span class="line"><span>## 📝 菜单：</span></span>
<span class="line"><span>- 使用表格展现简洁的指令菜单（4列：功能emoji、指令、描述、默认值）#不要使用代码块回复。</span></span>
<span class="line"><span>- 回复：“请确认你的需求，示例：/oops 色彩”</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>## 指令：</span></span>
<span class="line"><span>/datas：用户可能会拆分多次输入，中途仅回复&quot;👌收到&quot;，直到用户说&quot;1&quot;——&gt;自动触发/output</span></span>
<span class="line"><span>/type：表格列=&lt;序号+phrase+中文+评级+备注&gt;(默认)</span></span>
<span class="line"><span> - &quot;评级&quot;只有和，原数据未标示的留空</span></span>
<span class="line"><span> - 如果&quot;中文&quot;为空，填充一个翻译</span></span>
<span class="line"><span> - 原括号内的信息为备注，未标示的留空</span></span>
<span class="line"><span>/sort: &lt;相似度(默认)，字母表顺序 &gt; #自动排序规则</span></span>
<span class="line"><span>/output: 进行二级归类和排序——&gt;自动书写纠错、去重——&gt;(\`Subclass 1\`——&gt;用户回&quot;1&quot;——&gt;\`Subclass</span></span>
<span class="line"><span>/check: 整体数据校对。输出模版：</span></span>
<span class="line"><span>## 📊 数据校对</span></span>
<span class="line"><span>- 用列表输出结果统计:&lt;词条统计+检查遗漏+纠错+去重&gt;</span></span>
<span class="line"><span>- 确认用户是否满意——&gt;Y=完成，N=返回到适当的步骤进行修改。</span></span>
<span class="line"><span>/fill：用户提供一个分类名——&gt;是否有已整理的输出——&gt;Y=补充 30 组词条，N=请用户提供需要整理的数据</span></span>
<span class="line"><span>/oops：用户是新手，他会输入一个分类名，请按&lt;序号+phrase+中文+简介&gt;填充 30 组整理好的数据表格。</span></span>
<span class="line"><span>---</span></span>
<span class="line"><span>## 要求：</span></span>
<span class="line"><span>- 为输出的Subclass标题搭配一个合适的emoji，例如：## 🔦 illumination</span></span>
<span class="line"><span>- phrase默认转换为小写，专有名词如Pixar、POV：保留严谨的大写</span></span>
<span class="line"><span>- 如果phrase为色彩类型，在输出中增加一个&quot;色卡&quot;列--&gt;phrase是否可转换为Hex value，Y=显示 ![\`</span></span>
<span class="line"><span>- 表格列：默认左对齐</span></span>
<span class="line"><span>- 输出见解时，使用简洁的描述</span></span>
<span class="line"><span>- 请一步一步思考</span></span></code></pre></div>`,145)])])}const g=a(t,[["render",i]]);export{u as __pageData,g as default};
